protocol_mapping = {'rrc': {}, 'nr-rrc': {}}


def get_first_n_bytes(n, hex_str):
    """
    Retuns n first bytes
    :param n:
    :param hex_str:
    :return:
    """
    return str(hex_str)[0:int(n)]


def convert_to_bin(hex_str, length):
    """
    Converts to bin with beginning filled with 0 to length
    :param hex_str:
    :param length:
    :return:
    """
    return bin(int(str(hex_str), 16))[2:].zfill(int(length))


def convert_bin_to_dec(bin_str):
    """
    Converts bin to decimal
    :param bin_str:
    :return:
    """
    return int(str(bin_str), 2)


def get_value_of_n_bit(n, bit_str):
    """
    Returns int value of n-th bit in bitstring
    :param n:
    :param bit_str:
    :return:
    """
    return int(str(bit_str)[int(n) - 1])


def get_str_value_of_bits_in_range(start_bit, stop_bit, bit_str):
    """
    Returns n bits from given range as string
    :param start_bit:
    :param stop_bit:
    :param bit_str:
    :return:
    """
    return str(bit_str)[int(start_bit) - 1:int(stop_bit)]


def compare_bits(list_of_bits_to_1, bitstring):
    """
    Compares if given bits are set to 1 n bitstring
    :param list_of_bits_to_1:
    :param bitstring:
    :return:
    """
    for index in range(1, len(bitstring) + 1):
        if index in list_of_bits_to_1:
            if int(get_value_of_n_bit(index, bitstring)) != 1:
                return False
        else:
            if int(get_value_of_n_bit(index, bitstring)) != 0:
                return False
    return True


def get_n_bytes_and_convert_to_bitstring(hex_str, num_of_hex_bytes_needed):
    """
    Gets n bytes from hex string and converts it to bitstring
    :param hex_str:
    :param num_of_hex_bytes_needed:
    :return:
    """
    bytes = get_first_n_bytes(num_of_hex_bytes_needed, hex_str)
    bitstring = convert_to_bin(bytes, (8 / 2) * num_of_hex_bytes_needed)  # 8/2 - because of 2 hex symbols per byte
    return bitstring


