def _get_sibtype(bitstring):
    if get_value_of_n_bit(2, bitstring) == 1:
        # c1 choice index = 0
        return 'SystemInformationBlockType1'
    else:
        # checking extension flag
        if get_value_of_n_bit(10, bitstring) == 0:
            # choice selected from 4 bits 11-14
            return 'SystemInformationBlockType' + str(2 + int(get_str_value_of_bits_in_range(11, 14, bitstring), 2))
        else:
            # choice selected from 5 bits 12-17
            # starting reading from 11 because string numbered from 0 not 1
            choice_index = int(get_str_value_of_bits_in_range(12, 17, bitstring), 2)
            sib_num = sib_extention_choice_to_num[choice_index]
            sib_release = sib_type_to_release[sib_num]
            return 'SystemInformationBlockType{}-r{}'.format(sib_num, sib_release)


def _get_sibtype_nr(bitstring):
    sib_number_to_release_extension = {'10': '-r16',
                                       '11': '-r16',
                                       '12': '-r16',
                                       '13': '-r16',
                                       '14': '-r16',
                                       '15': '-r17',
                                       '16': '-r17',
                                       '17': '-r17',
                                       '18': '-r17',
                                       '19': '-r17',
                                       '20': '-r17',
                                       '21': '-r17'
                                       }
    if get_value_of_n_bit(2, bitstring) == 1:
        # c1 choice index = 0
        return 'SIB1'
    else:
        # checking extension flag
        if get_value_of_n_bit(11, bitstring) == 0:
            sequence_length = int(get_str_value_of_bits_in_range(6, 10, bitstring), 2) + 1  # WA , bits shows 3, while 4 is decoded
            # choice selected from 4 bits 12-14
            if sequence_length == 1:
                sib_num = str(2 + int(get_str_value_of_bits_in_range(12, 14, bitstring), 2))
                return 'SIB' + sib_num
            else:
                autogenerated_sibs = ['SIB{}'.format(sib_num) for sib_num in range(2, 2 + int(sequence_length))]
                autogenerated_sibs.append('SystemInformation')
                return autogenerated_sibs
        else:
            sequence_length = int(get_str_value_of_bits_in_range(6, 10, bitstring), 2) + 1  # WA , bits shows 3, while 4 is decoded
            if sequence_length == 1:
                sib_num = str(10 + int(get_str_value_of_bits_in_range(13, 18, bitstring), 2))
                assert sib_num in sib_number_to_release_extension, \
                    'Cannot find extension for sib number: {}'.format(sib_num)
                return 'SIB{}{}'.format(sib_num, sib_number_to_release_extension[sib_num])
            else:
                raise Exception('Sequence of more than 1 (got: {}) sib messages not supported for SIBs > 9'
                                .format(sequence_length))


def _get_sibtype_br(bitstring):
    suffix = "-BR-r13"
    if get_value_of_n_bit(2, bitstring) == 1:
        # c1 choice index = 0
        return 'SystemInformationBlockType1' + suffix
    else:
        """
        Below message types are not 3GPP compliant! DL-BCCH-SCH-BR contains the same message types as DL-BCCH-SCH channel, e.g.
        SystemInformationBlockType2. To be able to differentiate between DL-BCCH-SCH channels, different naming for -BR types were applied:
        - for SIBs without extension : '-BR-r13' suffix was added, to be compliant with SIB1-BR
        - for SIBs with release extension <= 13: '-rxx' release extension was removed and '-BR-r13' suffix was added,
        - for SIBs with release extension > 13: '-rXX' release extension was removed and '-BR-rXX' suffix was added, the release number was
        copied from orinal message to '-BR-rXX' suffix
        """
        # checking extension flag
        if get_value_of_n_bit(10, bitstring) == 0:
            # choice selected from 4 bits 11-14
            return 'SystemInformationBlockType' + str(
                2 + int(get_str_value_of_bits_in_range(11, 14, bitstring), 2)) + suffix
        else:
            # choice selected from 5 bits 12-17
            # starting reading from 11 because string numbered from 0 not 1
            sib_num = 12 + int(get_str_value_of_bits_in_range(12, 17, bitstring), 2)
            release = sib_type_to_release[sib_num]
            release = release if int(release) > 13 else 13
            return 'SystemInformationBlockType{}-BR-r{}'.format(sib_num, release)


def _get_sibtype_nb(bitstring):
    if get_value_of_n_bit(2, bitstring) == 1:
        # c1 choice index = 0
        return 'SystemInformationBlockType1-NB'
    else:
        # checking extension flag
        if get_value_of_n_bit(11, bitstring) == 0:
            # choice selected from 3 bits 12-14
            sib_num = nb_sib_choice_to_sib_number[int(get_str_value_of_bits_in_range(12, 14, bitstring), 2)]
            sib_release = nb_sib_num_to_release[sib_num]
            return 'SystemInformationBlockType{}-NB-r{}'.format(sib_num, sib_release)
        else:
            # checking bits 13-18
            choice_index = int(get_str_value_of_bits_in_range(13, 18, bitstring), 2)
            sib_num = nb_sib_extensions_choice_to_sib_number[choice_index]
            sib_release = nb_sib_num_to_release[sib_num]
            return 'SystemInformationBlockType{}-NB-r{}'.format(sib_num, sib_release)


def get_dl_ccch_message(hex_str):
    """
    Return dl_ccch message type, supported:
    RRCConnectionReestablishment
    RRCConnectionReestablishmentReject
    RRCConnectionReject
    RRCConnectionSetup
    :param hex_str:
    :return:
    """
    num_of_hex_bytes_needed = 2
    bitstring = get_n_bytes_and_convert_to_bitstring(hex_str, num_of_hex_bytes_needed)
    if get_value_of_n_bit(1, bitstring) == 0:
        two_bits = get_str_value_of_bits_in_range(2, 3, bitstring)
        dec_2_bits = convert_bin_to_dec(two_bits)
        try:
            return dl_ccch_c1_choice_to_message_type[dec_2_bits], None
        except Exception:
            raise Exception('DL-CCCH cannot find mapping for c1 choice: {} in mapping: {}'.format(dec_2_bits,
                                                                                                  dl_ccch_c1_choice_to_message_type))
    else:
        raise Exception('DL-CCCH extensions other than c1 not supported')


def get_dl_ccch_message_nr(hex_str):
    """
    Return dl_ccch from nr-rrc message type, supported:
    RRCReject
    RRCSetup
    spare2
    spare1
    :param hex_str:
    :return:
    """
    num_of_hex_bytes_needed = 2
    bitstring = get_n_bytes_and_convert_to_bitstring(hex_str, num_of_hex_bytes_needed)
    if get_value_of_n_bit(1, bitstring) == 0:
        two_bits = get_str_value_of_bits_in_range(2, 3, bitstring)
        dec_2_bits = convert_bin_to_dec(two_bits)
        try:
            return dl_ccch_c1_choice_to_message_type_nr[dec_2_bits], None
        except Exception:
            raise Exception('DL-CCCH NR cannot find mapping for c1 choice: {} in mapping: {}'
                            .format(dec_2_bits, dl_ccch_c1_choice_to_message_type_nr))
    else:
        raise Exception('DL-CCCH NR extensions other than c1 not supported')


def get_dl_ccch_message_nb(hex_str):
    """
    Return dl_ccch_nb message type, supported:
    RRCConnectionReestablishment-NB
    RRCConnectionReestablishmentReject-NB
    RRCConnectionReject-NB
    RRCConnectionSetup-NB
    :param hex_str:
    :return:
    """
    num_of_hex_bytes_needed = 1
    bitstring = get_n_bytes_and_convert_to_bitstring(hex_str, num_of_hex_bytes_needed)
    if get_value_of_n_bit(1, bitstring) == 0:
        # get int bit value form bits 2-4
        three_bits = int(get_str_value_of_bits_in_range(2, 4, bitstring), 2)
        try:
            return dl_ccch_nb_c1_choice_to_message_type[three_bits], None
        except Exception:
            raise Exception('DL-CCCH-NB cannot find mapping for c1 choice: {} in mapping: {}'
                            .format(three_bits, dl_ccch_nb_c1_choice_to_message_type))
    else:
        raise Exception('DL-CCCH-NB extensions other than c1 not supported')


def _get_ul_ccch_message_c1(bitstring):
    one_bit = get_value_of_n_bit(2, bitstring)
    try:
        return ul_ccch_c1_choice_to_message_type[one_bit], None
    except Exception:
        raise Exception('UL-CCCH cannot find mapping for c1 choice: {} in mapping: {}'
                        .format(one_bit, ul_ccch_c1_choice_to_message_type))


def _get_ul_ccch_message_non_c1(bitstring):
    one_bit = get_value_of_n_bit(2, bitstring)
    if one_bit == 0:  # choice c2, only single message type inside
        return ul_ccch_c2_choice_to_message_type, None
    elif one_bit == 1:  # messageClassExtenions future
        raise Exception('UL-CCCH extensions other than c1,c2 not supported')


def get_ul_ccch_message(hex_str):
    """
    Return ul_ccch message type, supported:
    RRCConnectionReestablishmentRequest
    RRCConnectionRequest
    RRCConnectionResumeRequest-r13
    :param hex_str:
    :return:
    """
    num_of_hex_bytes_needed = 1
    bitstring = get_n_bytes_and_convert_to_bitstring(hex_str, num_of_hex_bytes_needed)
    if get_value_of_n_bit(1, bitstring) == 0:
        return _get_ul_ccch_message_c1(bitstring)
    elif get_value_of_n_bit(1, bitstring) == 1:  # message class extension
        return _get_ul_ccch_message_non_c1(bitstring)


def get_ul_ccch_message_nr(hex_str):
    """
    Return ul_ccch message type, supported:
    RRCSetupRequest
    RRCResumeRequest
    RRCReestablishmentRequest
    RRCSystemInfoRequest
    RRCSetupRequest1 in case length of hexstr >=8
    :param hex_str:
    :return:
    """
    num_of_hex_bytes_needed = 1
    bitstring = get_n_bytes_and_convert_to_bitstring(hex_str, num_of_hex_bytes_needed)
    if get_value_of_n_bit(1, bitstring) == 0:
        two_bits = get_str_value_of_bits_in_range(2, 3, bitstring)
        dec_2_bits = convert_bin_to_dec(two_bits)
        try:
            return ul_ccch_c1_choice_to_message_type_nr[dec_2_bits], None
        except Exception:
            raise Exception('UL-CCCH NR cannot find mapping for c1 choice: {} in mapping: {}'
                            .format(dec_2_bits, ul_ccch_c1_choice_to_message_type_nr))
    else:
        raise Exception('UL-CCCH NR extensions other than c1 not supported')


def get_ul_ccch1_message_nr(hex_str):
    """
    Return ul_ccch1 message type, supported:
    RRCResumeRequest1
    :param hex_str:
    :return:
    """
    num_of_hex_bytes_needed = 1
    bitstring = get_n_bytes_and_convert_to_bitstring(hex_str, num_of_hex_bytes_needed)
    if get_value_of_n_bit(1, bitstring) == 0:
        two_bits = get_str_value_of_bits_in_range(2, 3, bitstring)
