def get_dl_mcch_message(hex_str):
    """
    Returns type for DL-MCCH message. Supported:
    c1:
    MBSFNAreaConfiguration-r9
    c2:
    MBMSCountingRequest-r10
    :param hex_str:
    :return:
    """
    num_of_hex_bytes_needed = 1
    bitstring = get_n_bytes_and_convert_to_bitstring(hex_str, num_of_hex_bytes_needed)
    if get_value_of_n_bit(1, bitstring) == 0:
        # c1 extension, only one message supported
        return 'MBSFNAreaConfiguration-r9', None
    else:
        # messageClassExtension
        if get_value_of_n_bit(2, bitstring) == 0:
            # c2 extension, only one message supported
            return 'MBMSCountingRequest-r10', None
        else:
            raise Exception('DL-MCCH messageClassExtension other than c2 not supported')


